insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'primitive-types'), 'variable', 'A named storage location holding a value of a declared type.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'primitive-types'), 'constant', 'A variable declared final; its value cannot be reassigned after initialization.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'primitive-types'), 'cast', 'An explicit conversion of a value from one type to another, e.g. (int) 4.7.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'primitive-types'), 'operator precedence', 'The order in which operators are evaluated within an expression.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'primitive-types'), 'overflow', 'What happens when a computed value exceeds the range its type can represent.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'using-objects'), 'object', 'A runtime instance of a class, allocated in memory and accessed via a reference.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'using-objects'), 'constructor', 'A special method that initializes a newly created object.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'using-objects'), 'reference', 'A variable that stores the memory location of an object, not the object itself.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'using-objects'), 'alias', 'Two references pointing to the same object; changes through one are visible through the other.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'using-objects'), 'null', 'A reference that points to no object.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'boolean-expressions-and-if-statements'), 'short-circuit evaluation', 'Stopping evaluation of a Boolean expression as soon as the result is determined.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'boolean-expressions-and-if-statements'), 'De Morgan''s laws', 'Rules for distributing a negation over && and ||: !(a && b) == !a || !b.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'iteration'), 'accumulator', 'A variable that collects a running result (sum, count, product) across loop iterations.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'iteration'), 'sentinel value', 'A special input value that signals a loop to stop.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'writing-classes'), 'encapsulation', 'Bundling data with the methods that operate on it, and restricting direct access to that data.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'writing-classes'), 'this', 'A reference to the current object, used to disambiguate fields from parameters of the same name.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'arrays'), 'index', 'The zero-based position of an element within an array.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'arrays'), 'parallel arrays', 'Two or more arrays whose elements at the same index describe the same real-world entity.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'arraylist'), 'generic type', 'A type parameter, like <Integer>, that specifies what an ArrayList holds.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'arraylist'), 'autoboxing', 'Java''s automatic conversion of a primitive (int) into its wrapper object (Integer).');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = '2d-arrays'), 'row-major order', 'Traversing a 2D array one full row at a time before moving to the next row.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = '2d-arrays'), 'ragged array', 'A 2D array whose rows are not all the same length.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'inheritance'), 'polymorphism', 'The ability of a reference of a superclass type to invoke overridden behavior defined in a subclass.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'inheritance'), 'dynamic method dispatch', 'Java''s rule that an overridden method call resolves to the object''s actual runtime type, not its declared reference type.');
insert into vocabulary_terms (unit_id, term, definition) values ((select id from units where slug = 'recursion'), 'base case', 'The condition under which a recursive method returns directly without calling itself again.');
