insert into syntax_templates (topic, title, description, template_code, example_code, common_mistake, difficulty) values ('Primitive Types', 'Arithmetic Operators', 'The operators +, -, *, /, and % combine numeric operands. / and % behave differently for integer vs. floating-point operands.', 'a + b   a - b   a * b   a / b   a % b', 'int quotient = 17 / 5;   // 3
int remainder = 17 % 5;  // 2', 'Expecting int / int to produce a decimal result.', 'easy');
insert into syntax_templates (topic, title, description, template_code, example_code, common_mistake, difficulty) values ('Primitive Types', 'Casting', 'An explicit conversion of a value from one type to another, written as (type) value.', '(int) doubleValue
(double) intValue', 'double price = 4.75;
int dollars = (int) price;  // 4, not rounded', 'Assuming a cast rounds to the nearest value instead of truncating.', 'easy');
insert into syntax_templates (topic, title, description, template_code, example_code, common_mistake, difficulty) values ('Using Objects', 'Core String Methods', 'String provides methods for inspecting and deriving new Strings: length(), substring(), indexOf(), equals(), and more. Strings are immutable — these methods never modify the original String.', 'str.length()
str.substring(start, end)
str.indexOf(target)
str.equals(other)', 'String word = "computer";
int len = word.length();       // 8
String sub = word.substring(0, 4); // "comp"', 'Using == instead of .equals() to compare String content.', 'easy');
insert into syntax_templates (topic, title, description, template_code, example_code, common_mistake, difficulty) values ('Iteration', 'For Loop', 'A loop with an initialization, condition, and update clause, ideal when the number of iterations is known in advance.', 'for (int i = 0; i < n; i++) {
    // body
}', 'for (int i = 0; i < 5; i++) {
    System.out.println(i);
}
// prints 0 1 2 3 4', 'Using <= n instead of < n, causing one extra iteration.', 'easy');
insert into syntax_templates (topic, title, description, template_code, example_code, common_mistake, difficulty) values ('ArrayList', 'Core ArrayList Methods', 'ArrayList<E> supports add, remove, get, set, and size for managing a resizable, generically-typed collection.', 'list.add(value)
list.get(index)
list.set(index, value)
list.remove(index)
list.size()', 'ArrayList<String> names = new ArrayList<>();
names.add("Ada");
names.add("Al");
names.remove(0);
// names is now ["Al"]', 'Confusing remove(int index) with remove(Object o) — remove(1) removes the element at index 1, not the value 1.', 'easy');
insert into syntax_templates (topic, title, description, template_code, example_code, common_mistake, difficulty) values ('Inheritance', 'extends and super', 'A subclass inherits fields and methods from its superclass using extends, and can call the superclass''s constructor or methods using super.', 'public class Dog extends Animal {
    public Dog(String name) {
        super(name);
    }
}', 'class Animal {
    protected String name;
    public Animal(String name) { this.name = name; }
}
class Dog extends Animal {
    public Dog(String name) { super(name); }
}', 'Forgetting that super(...) must be the first statement in a subclass constructor.', 'easy');
insert into syntax_templates (topic, title, description, template_code, example_code, common_mistake, difficulty) values ('Errors', 'Common Runtime Errors', 'Exceptions thrown while a program executes, as opposed to compiler errors caught before the program runs.', 'NullPointerException
ArrayIndexOutOfBoundsException
ArithmeticException
ClassCastException', 'int[] arr = new int[3];
System.out.println(arr[5]); // ArrayIndexOutOfBoundsException', 'Confusing a runtime exception with a compiler error — this code compiles fine and fails only when it executes.', 'easy');

