insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'primitive-types'), 'Variable declarations', 'type_from_memory', 'Declare an int named age and initialize it to 16.', null, 'int age = 16;', 'int declares the type, age is the identifier, and = 16; assigns the initial value.', 'intro');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'primitive-types'), 'Variable declarations', 'type_from_memory', 'Declare a double named price and initialize it to 4.99.', null, 'double price = 4.99;', 'double stores decimal values; the literal 4.99 is already a double by default.', 'intro');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'boolean-expressions-and-if-statements'), 'Variable declarations', 'type_from_memory', 'Declare a boolean named isEnrolled and initialize it to true.', null, 'boolean isEnrolled = true;', 'boolean variables may only hold true or false — never 0 or 1 as in some other languages.', 'intro');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'primitive-types'), 'Constants', 'type_from_memory', 'Declare a constant int named MAX_SCORE equal to 100 that cannot be reassigned.', null, 'final int MAX_SCORE = 100;', 'final prevents reassignment after initialization; constants are conventionally named in SCREAMING_SNAKE_CASE.', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'using-objects'), 'String methods', 'type_from_memory', 'Declare a String named greeting and initialize it to "Hello".', null, 'String greeting = "Hello";', 'String is a class, not a primitive, but literals can still be assigned directly without new.', 'intro');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'primitive-types'), 'Arithmetic expressions', 'type_from_memory', 'Write an expression that stores the remainder of dividing total by 3 into a variable named remainder.', null, 'int remainder = total % 3;', '% returns the remainder of integer division.', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'primitive-types'), 'Casting', 'type_from_memory', 'Cast the double variable price to an int and store it in a new variable named dollars.', null, 'int dollars = (int) price;', 'Casting a double to int truncates the decimal portion; it does not round.', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'primitive-types'), 'Arithmetic expressions', 'type_from_memory', 'Increase the variable total by 5 using compound assignment.', null, 'total += 5;', 'total += 5; is shorthand for total = total + 5;', 'intro');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'boolean-expressions-and-if-statements'), 'If statements', 'type_from_memory', 'Write an if statement that prints "Passing" when score is at least 70.', null, 'if (score >= 70) {
    System.out.println("Passing");
}', '>= includes the boundary value 70 itself.', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'boolean-expressions-and-if-statements'), 'If-else chains', 'type_from_memory', 'Write an if-else statement that prints "Even" if num is even and "Odd" otherwise.', null, 'if (num % 2 == 0) {
    System.out.println("Even");
} else {
    System.out.println("Odd");
}', 'num % 2 == 0 is the standard even-number test.', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'boolean-expressions-and-if-statements'), 'Else-if chains', 'type_from_memory', 'Write an else-if chain assigning letter grades: "A" for score >= 90, "B" for score >= 80, else "C".', null, 'if (score >= 90) {
    letter = "A";
} else if (score >= 80) {
    letter = "B";
} else {
    letter = "C";
}', 'Conditions are checked top to bottom; order from highest threshold to lowest matters.', 'medium');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'boolean-expressions-and-if-statements'), 'Boolean expressions', 'compare_similar_syntax', 'Rewrite !(a && b) using De Morgan''s law so the negation is distributed.', null, '!a || !b', 'De Morgan''s law: !(a && b) is equivalent to !a || !b.', 'medium');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'iteration'), 'For loops', 'type_from_memory', 'Write a for loop that prints the integers from 0 through 9.', null, 'for (int i = 0; i < 10; i++) {
    System.out.println(i);
}', 'i < 10 stops after printing 9, since i becomes 10 and the condition fails.', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'iteration'), 'While loops', 'type_from_memory', 'Write a while loop that continues while score is less than 100.', null, 'while (score < 100) {
    // loop body
}', 'The condition is checked before each iteration; the loop body must eventually change score.', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'iteration'), 'Nested loops', 'type_from_memory', 'Write nested for loops that print a 3x3 grid of asterisks, one row per line.', null, 'for (int row = 0; row < 3; row++) {
    for (int col = 0; col < 3; col++) {
        System.out.print("*");
    }
    System.out.println();
}', 'The inner loop completes fully for each iteration of the outer loop.', 'medium');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'arrays'), 'Array traversal', 'type_from_memory', 'Write an enhanced for loop that prints every element of the int array scores.', null, 'for (int score : scores) {
    System.out.println(score);
}', 'Enhanced for loops read each element but cannot modify the underlying array by index.', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'writing-classes'), 'Method headers', 'method_header_drill', 'Write a method header for a public, static method named max that takes two ints and returns an int.', null, 'public static int max(int a, int b)', 'Order is: access modifier, static/instance, return type, name, parameter list.', 'medium');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'writing-classes'), 'Constructors', 'type_from_memory', 'Write a constructor for a class Student that takes a String name and assigns it to an instance field this.name.', null, 'public Student(String name) {
    this.name = name;
}', 'A constructor shares its class''s name and has no return type, not even void.', 'medium');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'arrays'), 'Arrays', 'type_from_memory', 'Declare an integer array named values with a length of 10.', null, 'int[] values = new int[10];', 'new int[10] allocates 10 slots, each initialized to 0 by default.', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'arrays'), 'Array traversal', 'type_from_memory', 'Write an indexed for loop that prints every element of the array values.', null, 'for (int i = 0; i < values.length; i++) {
    System.out.println(values[i]);
}', 'values.length is a field (no parentheses), unlike String''s length() method.', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'arraylist'), 'ArrayList', 'type_from_memory', 'Declare an ArrayList of Strings named names.', null, 'ArrayList<String> names = new ArrayList<String>();', 'The diamond operator <> lets the compiler infer the type argument on the right-hand side.', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'arraylist'), 'ArrayList', 'type_from_memory', 'Write an enhanced for loop that prints every element of the ArrayList<String> names.', null, 'for (String name : names) {
    System.out.println(name);
}', 'ArrayList supports the enhanced for loop just like arrays do.', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'arraylist'), 'ArrayList', 'type_from_memory', 'Add "Ada" to the ArrayList names, then remove the element at index 0.', null, 'names.add("Ada");
names.remove(0);', 'remove(int index) removes by position; remove(Object o) removes by value — these are different overloads.', 'medium');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = '2d-arrays'), '2D arrays', 'type_from_memory', 'Declare a 2D int array named grid with 3 rows and 4 columns.', null, 'int[][] grid = new int[3][4];', 'The first bracket is the number of rows, the second is the number of columns per row.', 'medium');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'inheritance'), 'Method overriding', 'type_from_memory', 'Write an overridden toString() method that returns the String "Animal".', null, '@Override
public String toString() {
    return "Animal";
}', '@Override isn''t required but documents intent and lets the compiler catch signature mismatches.', 'medium');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'recursion'), 'Recursion', 'type_from_memory', 'Write a recursive method factorial(int n) that returns n! for n >= 0.', null, 'public static int factorial(int n) {
    if (n == 0) {
        return 1;
    }
    return n * factorial(n - 1);
}', 'n == 0 is the base case; each recursive call moves n closer to 0.', 'hard');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'using-objects'), 'Compare similar syntax', 'compare_similar_syntax', 'Write the correct way to compare two String objects, name1 and name2, for equal content.', null, 'name1.equals(name2)', '== compares references for objects; .equals() compares the actual content of the Strings.', 'medium');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'arrays'), 'Compare similar syntax', 'compare_similar_syntax', 'Write the expression that gets the number of elements in the int array data.', null, 'data.length', 'Arrays use the .length field (no parentheses).', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'using-objects'), 'Compare similar syntax', 'compare_similar_syntax', 'Write the expression that gets the number of characters in the String word.', null, 'word.length()', 'String uses the .length() method (with parentheses) — the opposite convention from arrays.', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'arraylist'), 'Compare similar syntax', 'compare_similar_syntax', 'Write the expression that gets the number of elements in the ArrayList<String> list.', null, 'list.size()', 'ArrayList uses .size(), a third convention distinct from both array.length and String.length().', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'writing-classes'), 'Compare similar syntax', 'compare_similar_syntax', 'Write a method header for a static method named createDefault that returns a new Student with no parameters.', null, 'public static Student createDefault()', 'static methods belong to the class itself and can be called without an instance: Student.createDefault().', 'medium');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'arraylist'), 'Compare similar syntax', 'compare_similar_syntax', 'State the key structural difference between an array and an ArrayList in one phrase.', null, 'An array has a fixed size; an ArrayList can grow and shrink.', 'This is the core tradeoff the AP exam expects you to articulate when asked to justify a data structure choice.', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'iteration'), 'Plain English to Java', 'plain_english_to_java', 'Create a while loop that continues while score is less than 100.', null, 'while (score < 100) {
    // ...
}', 'Translate the condition directly: "while score is less than 100" becomes while (score < 100).', 'easy');
insert into syntax_questions (unit_id, topic, drill_type, prompt, starter_code, correct_answer, explanation, difficulty) values ((select id from units where slug = 'iteration'), 'Java to Plain English', 'java_to_plain_english', 'Explain in plain English what this loop does: for (int i = arr.length - 1; i >= 0; i--) { System.out.println(arr[i]); }', null, 'It prints the elements of arr in reverse order, from the last index down to the first.', 'Starting at length - 1 and decrementing to 0 walks the array backward.', 'medium');

