with new_question as (
  insert into mcq_questions (unit_id, topic, prompt, code, explanation, difficulty, estimated_seconds, skills_tested, common_misconception, hint, published)
  values ((select id from units where slug = 'writing-classes'), 'this keyword', 'In the method below, the parameter is named x, the same as the instance field. What would happen if this.x = x; were replaced with x = x;?', 'public void setX(int x) {
    this.x = x;
}', 'Inside the method body, an unqualified x refers to the parameter (it shadows the field), so x = x; is a no-op on the field.', 'medium', 60, ARRAY['this keyword', 'scope'], 'Assuming Java always knows you mean the field when a parameter shares its name.', null, true)
  returning id
