insert into mcq_choices (question_id, choice_label, choice_text, is_correct, explanation, sort_order)
select id, v.label, v.text, v.is_correct, v.explanation, v.sort_order
from new_question, (values
  ('A', 'The instance field x would be updated correctly, exactly as before.', false, 'Without this, x on the left refers to the local parameter, not the field.', 0),
  ('B', 'The parameter would be assigned to itself, and the instance field would remain unchanged.', true, 'Inside the method body, an unqualified x refers to the parameter (it shadows the field), so x = x; is a no-op on the field.', 1),
  ('C', 'The code would fail to compile.', false, 'x = x; is legal Java, just logically useless here — it compiles without error.', 2),
  ('D', 'A NullPointerException would be thrown at runtime.', false, 'No object is being dereferenced in a way that could throw NPE here.', 3)
) as v(label, text, is_correct, explanation, sort_order);
