insert into mcq_choices (question_id, choice_label, choice_text, is_correct, explanation, sort_order)
select id, v.label, v.text, v.is_correct, v.explanation, v.sort_order
from new_question, (values
  ('A', 'result is false; && short-circuits after (x != 0) is false, so 10 / x is never evaluated.', true, 'Because the left operand of && is false, Java skips evaluating the right operand entirely, avoiding the division by zero.', 0),
  ('B', 'result is true; Java evaluates both sides regardless.', false, '&& in Java is short-circuiting; it does not always evaluate both operands.', 1),
  ('C', 'The code throws an ArithmeticException.', false, 'The division 10 / x is never reached because of short-circuit evaluation.', 2),
  ('D', 'result is false, but only because 10 / x evaluates to a value less than 1.', false, '10 / x is never evaluated at all in this trace — the short-circuit happens first.', 3)
